import { useState, useCallback, useMemo, useRef } from 'react';
import type { SystemSetting, UpdateSettingRequest, UseSystemSettingsReturn } from '../types';
import { SystemSettingsApiClient } from '../utils/systemSettingsApi';
import { useCedrosLoginAdminClientContext } from './useCedrosLoginAdminClientContext';

/**
 * Hook for managing system settings (admin only).
 *
 * Provides CRUD operations for system-wide configuration settings
 * stored in the database. Only accessible to system administrators.
 *
 * @example
 * ```tsx
 * function SystemSettingsPanel() {
 *   const {
 *     settings,
 *     isLoading,
 *     error,
 *     fetchSettings,
 *     updateSettings,
 *     getValue,
 *   } = useSystemSettings();
 *
 *   useEffect(() => {
 *     fetchSettings();
 *   }, [fetchSettings]);
 *
 *   const handleSave = async () => {
 *     await updateSettings([
 *       { key: 'privacy_period_secs', value: '1209600' },
 *     ]);
 *   };
 *
 *   return (
 *     <div>
 *       {Object.entries(settings).map(([category, items]) => (
 *         <section key={category}>
 *           <h3>{category}</h3>
 *           {items.map(item => (
 *             <div key={item.key}>
 *               {item.key}: {item.value}
 *             </div>
 *           ))}
 *         </section>
 *       ))}
 *     </div>
 *   );
 * }
 * ```
 */
export function useSystemSettings(): UseSystemSettingsReturn {
  const { config, authState, _internal } = useCedrosLoginAdminClientContext();

  const [settings, setSettings] = useState<Record<string, SystemSetting[]>>({});
  const [isLoading, setIsLoading] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const requestIdRef = useRef(0);

  const apiClient = useMemo(
    () =>
      new SystemSettingsApiClient(
        config.serverUrl,
        config.requestTimeout,
        config.retryAttempts,
        _internal?.getAccessToken
      ),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  // Use ref to avoid apiClient in callback dependencies
  const apiClientRef = useRef(apiClient);
  apiClientRef.current = apiClient;

  const fetchSettings = useCallback(async () => {
    if (authState !== 'authenticated') {
      setSettings({});
      return;
    }

    setIsLoading(true);
    setError(null);
    const requestId = ++requestIdRef.current;

    try {
      const response = await apiClientRef.current.getSettings();
      if (requestId !== requestIdRef.current) return;
      setSettings(response.settings);
    } catch (err) {
      if (requestId !== requestIdRef.current) return;
      setError(err instanceof Error ? err : new Error('Failed to fetch settings'));
    } finally {
      if (requestId === requestIdRef.current) {
        setIsLoading(false);
      }
    }
  }, [authState]);

  const updateSettings = useCallback(
    async (updates: UpdateSettingRequest[]): Promise<void> => {
      if (authState !== 'authenticated') {
        throw new Error('Not authenticated');
      }

      setIsUpdating(true);
      setError(null);

      try {
        await apiClientRef.current.updateSettings(updates);
        // Refresh settings after update
        await fetchSettings();
      } catch (err) {
        const error = err instanceof Error ? err : new Error('Failed to update settings');
        setError(error);
        throw error;
      } finally {
        setIsUpdating(false);
      }
    },
    [authState, fetchSettings]
  );

  const getValue = useCallback(
    (key: string): string | undefined => {
      for (const categorySettings of Object.values(settings)) {
        const found = categorySettings.find((s) => s.key === key);
        if (found) return found.value;
      }
      return undefined;
    },
    [settings]
  );

  return {
    settings,
    isLoading,
    isUpdating,
    error,
    fetchSettings,
    updateSettings,
    getValue,
  };
}
